//! Built-in email templates (Turkish + English).
//!
//! The DB seeds its own `email_templates`; the web layer falls back to
//! [`default_template`] when a tenant has no row for `(key, locale)`.
//! `body_html` is **content only** — [`crate::layout`] adds the branded frame.
//! Templates use the [`crate::template`] syntax; [`sample_context`] returns
//! realistic data for each key and documents the expected variables:
//!
//! * every template: `company.name`, `user.name` (except `staff_invite`)
//! * `action_url` — the main call-to-action link (generated by the app)
//! * `invoice.{number,total,due_date,paid_at,url,notes,days_overdue,suspension_date}`,
//!   `payment.method`
//! * `service.{name,domain,username,reason}`
//! * `ticket.{number,subject,reply_excerpt,staff_name,url}`
//! * `domain.{name,expires_on,days_left,renew_url,auto_renew}`
//! * `order.{number,total,summary,url}`
//! * `inviter.name`, `role.name`, `invitee.email`
//! * `staff_ticket`: `ticket.{number,subject,department,client_name,excerpt,is_new}`
//! * `expires_in_hours`, `expires_in_minutes`, `expires_in_days`, `request.ip`
//!
//! Amounts and dates are passed **pre-formatted** for the recipient's locale
//! (`"₺1.250,00"`, `"30.11.2026"`). Passwords are never put into emails.

use hos_core::domain::Locale;
use serde::Serialize;
use serde_json::{Value, json};

/// Template keys (`email_templates.key`).
pub mod keys {
    /// New account welcome.
    pub const WELCOME: &str = "welcome";
    /// Email address verification link.
    pub const EMAIL_VERIFICATION: &str = "email_verification";
    /// Password reset link.
    pub const PASSWORD_RESET: &str = "password_reset";
    /// New invoice issued.
    pub const INVOICE_CREATED: &str = "invoice_created";
    /// Payment received.
    pub const INVOICE_PAID: &str = "invoice_paid";
    /// Invoice past due.
    pub const INVOICE_OVERDUE: &str = "invoice_overdue";
    /// Service provisioned.
    pub const SERVICE_ACTIVATED: &str = "service_activated";
    /// Service suspended.
    pub const SERVICE_SUSPENDED: &str = "service_suspended";
    /// Staff replied to a ticket.
    pub const TICKET_REPLY: &str = "ticket_reply";
    /// Domain expiry reminder.
    pub const DOMAIN_EXPIRING: &str = "domain_expiring";
    /// Order received.
    pub const ORDER_CONFIRMATION: &str = "order_confirmation";
    /// Invitation to join the tenant's staff.
    pub const STAFF_INVITE: &str = "staff_invite";
    /// To staff: a client opened or replied to a ticket of their department.
    pub const STAFF_TICKET: &str = "staff_ticket";
    /// A quote with its secret accept link (client or prospect).
    pub const QUOTE: &str = "quote";
    /// Network status: an incident or maintenance affects the client's services.
    pub const NETWORK_NOTICE: &str = "network_notice";

    /// Every key.
    pub const ALL: &[&str] = &[
        WELCOME,
        EMAIL_VERIFICATION,
        PASSWORD_RESET,
        INVOICE_CREATED,
        INVOICE_PAID,
        INVOICE_OVERDUE,
        SERVICE_ACTIVATED,
        SERVICE_SUSPENDED,
        TICKET_REPLY,
        DOMAIN_EXPIRING,
        ORDER_CONFIRMATION,
        STAFF_INVITE,
        STAFF_TICKET,
        QUOTE,
        NETWORK_NOTICE,
    ];
}

/// A built-in template.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct DefaultTemplate {
    /// Template key (see [`keys`]).
    pub key: &'static str,
    /// Language.
    pub locale: Locale,
    /// Subject template.
    pub subject: &'static str,
    /// HTML content template (without layout).
    pub body_html: &'static str,
    /// Plain-text template.
    pub body_text: &'static str,
}

impl DefaultTemplate {
    /// As a render source for [`crate::template::render_email`].
    pub fn source(&self) -> crate::template::EmailTemplateSource<'static> {
        crate::template::EmailTemplateSource {
            subject: self.subject,
            body_html: self.body_html,
            body_text: Some(self.body_text),
        }
    }
}

/// All built-in templates (15 keys × tr/en).
pub fn default_templates() -> Vec<DefaultTemplate> {
    TEMPLATES.to_vec()
}

/// The built-in template for `key` in `locale`, if any.
pub fn default_template(key: &str, locale: Locale) -> Option<DefaultTemplate> {
    TEMPLATES
        .iter()
        .find(|t| t.key == key && t.locale == locale)
        .copied()
}

/// Realistic sample context for `key` (admin preview, tests). Unknown keys get
/// the shared `company` / `user` part only.
pub fn sample_context(key: &str) -> Value {
    let mut ctx = json!({
        "company": {
            "name": "Örnek Hosting",
            "url": "https://www.ornekhosting.com.tr",
            "support_email": "destek@ornekhosting.com.tr"
        },
        "user": {"name": "Ayşe Yılmaz", "email": "ayse@example.com"}
    });
    let panel = "https://panel.ornekhosting.com.tr";
    let extra = match key {
        keys::WELCOME => json!({"action_url": format!("{panel}/client")}),
        keys::EMAIL_VERIFICATION => json!({
            "action_url": format!("{panel}/auth/verify-email?token=Zk3x9QvJ2"),
            "expires_in_hours": 48
        }),
        keys::PASSWORD_RESET => json!({
            "action_url": format!("{panel}/auth/reset-password?token=pR4s7Lm1"),
            "expires_in_minutes": 60,
            "request": {"ip": "203.0.113.7"}
        }),
        keys::INVOICE_CREATED => json!({"invoice": {
            "number": "2026-00042",
            "total": "₺1.250,00",
            "due_date": "30.11.2026",
            "url": format!("{panel}/client/invoices/2026-00042"),
            "notes": "Havale/EFT ile ödemelerde açıklama alanına fatura numarasını yazınız."
        }}),
        keys::INVOICE_PAID => json!({
            "invoice": {
                "number": "2026-00042",
                "total": "₺1.250,00",
                "paid_at": "16.11.2026",
                "url": format!("{panel}/client/invoices/2026-00042")
            },
            "payment": {"method": "Kredi kartı"}
        }),
        keys::INVOICE_OVERDUE => json!({"invoice": {
            "number": "2026-00042",
            "total": "₺1.250,00",
            "due_date": "10.11.2026",
            "days_overdue": 6,
            "suspension_date": "21.11.2026",
            "url": format!("{panel}/client/invoices/2026-00042")
        }}),
        keys::SERVICE_ACTIVATED => json!({
            "service": {
                "name": "Kurumsal Hosting - Pro",
                "domain": "ornek-firma.com.tr",
                "username": "ornekfir"
            },
            "action_url": format!("{panel}/client/services/1")
        }),
        keys::SERVICE_SUSPENDED => json!({
            "service": {
                "name": "Kurumsal Hosting - Pro",
                "domain": "ornek-firma.com.tr",
                "reason": "Ödenmemiş fatura (#2026-00042)"
            },
            "action_url": format!("{panel}/client/invoices")
        }),
        keys::TICKET_REPLY => json!({"ticket": {
            "number": "TKT-1042",
            "subject": "SSL sertifikası kurulumu",
            "reply_excerpt": "Merhaba Ayşe Hanım,\nSertifikanız kuruldu; sitenizi https:// ile açabilirsiniz.",
            "staff_name": "Mehmet Kaya",
            "url": format!("{panel}/client/tickets/TKT-1042")
        }}),
        keys::DOMAIN_EXPIRING => json!({"domain": {
            "name": "ornek-firma.com.tr",
            "expires_on": "15.12.2026",
            "days_left": 29,
            "auto_renew": false,
            "renew_url": format!("{panel}/client/domains/ornek-firma.com.tr/renew")
        }}),
        keys::ORDER_CONFIRMATION => json!({"order": {
            "number": "ORD-2026-0815",
            "total": "₺2.499,00",
            "summary": "1 × Kurumsal Hosting - Pro (yıllık), 1 × ornek-firma.com.tr (1 yıl)",
            "url": format!("{panel}/client/orders/ORD-2026-0815")
        }}),
        keys::STAFF_INVITE => json!({
            "inviter": {"name": "Ali Demir"},
            "role": {"name": "Destek"},
            "invitee": {"email": "yeni.personel@ornekhosting.com.tr"},
            "action_url": format!("{panel}/auth/accept-invite?token=iNv8Qa"),
            "expires_in_days": 7
        }),
        keys::STAFF_TICKET => json!({
            "user": {"name": "Mehmet Kaya", "email": "mehmet@ornekhosting.com.tr"},
            "ticket": {
                "number": "TKT-1043",
                "subject": "E-postalarım gitmiyor",
                "department": "Teknik Destek",
                "client_name": "Ayşe Yılmaz",
                "excerpt": "Merhaba,\nDünden beri gönderdiğim e-postalar karşı tarafa ulaşmıyor.",
                "is_new": true
            },
            "action_url": format!("{panel}/admin/support/tickets/TKT-1043")
        }),
        keys::QUOTE => json!({
            "quote": {
                "number": "Q-00042",
                "subject": "Kurumsal e-posta ve VPS geçişi",
                "total": "₺18.240,00",
                "valid_until": "30 Kasım 2026"
            },
            "action_url": format!("{panel}/quote/0190c5e2-7b3a-7c51-9a1e-3f2b8c9d0e11?token=qT7wLm2")
        }),
        keys::NETWORK_NOTICE => json!({
            "incident": {
                "title": "İstanbul veri merkezinde planlı bakım",
                "kind": "maintenance",
                "status": "Planlandı",
                "impact": "Kısmi kesinti",
                "starts": "21 Kasım 2026 02:00",
                "message": "Depolama katmanında donanım yenilemesi yapılacaktır. Hizmetleriniz 15 dakikaya kadar erişilemez olabilir.",
                "services": "ornek-firma.com.tr, VPS Pro"
            },
            "action_url": format!("{panel}/status")
        }),
        _ => json!({}),
    };
    if let (Some(base), Value::Object(extra)) = (ctx.as_object_mut(), extra) {
        base.extend(extra);
    }
    ctx
}

