#[cfg(test)]
mod tests {
    use super::*;
    use crate::layout::{self, Brand, LayoutOptions};
    use crate::template::{Template, lookup, render_email};
    use std::collections::HashSet;

    #[test]
    fn catalog_is_complete_and_unique() {
        let all = default_templates();
        assert_eq!(all.len(), keys::ALL.len() * 2);
        let mut seen = HashSet::new();
        for t in &all {
            assert!(keys::ALL.contains(&t.key), "unknown key {}", t.key);
            assert!(
                seen.insert((t.key, t.locale)),
                "duplicate {} {}",
                t.key,
                t.locale
            );
        }
        for key in keys::ALL {
            for locale in Locale::ALL {
                assert!(default_template(key, *locale).is_some(), "{key} {locale}");
            }
        }
        assert!(default_template("nope", Locale::Tr).is_none());
    }

    #[test]
    fn every_template_renders_with_its_sample_context() {
        let brand = Brand {
            company_name: "Örnek Hosting".into(),
            unsubscribe_url: Some("https://panel.ornekhosting.com.tr/client/notifications".into()),
            support_email: Some("destek@ornekhosting.com.tr".into()),
            ..Brand::default()
        };
        for t in default_templates() {
            let ctx = sample_context(t.key);
            // Every referenced variable (also inside conditionals) is documented
            // by the sample context.
            for part in [t.subject, t.body_html, t.body_text] {
                for var in Template::parse(part).unwrap().variables() {
                    assert!(
                        lookup(&ctx, &var).is_some(),
                        "{} {}: `{var}` missing",
                        t.key,
                        t.locale
                    );
                }
            }
            let rendered = render_email(&t.source(), &ctx)
                .unwrap_or_else(|e| panic!("{} {}: {e}", t.key, t.locale));
            assert!(!rendered.subject.is_empty());
            assert!(!rendered.subject.contains(['\r', '\n']));
            assert!(!rendered.html.contains("{{"), "{} {}", t.key, t.locale);
            assert!(!rendered.text.contains("{{"), "{} {}", t.key, t.locale);

            let opts = LayoutOptions {
                preheader: Some(rendered.subject.clone()),
                locale: t.locale,
            };
            let wrapped = layout::apply(&brand, rendered, &opts);
            assert!(wrapped.html.starts_with("<!DOCTYPE html>"));
            let msg = wrapped.into_message(vec![hos_core::integrations::mailer::Mailbox::new(
                "ayse@example.com",
            )]);
            msg.validate().unwrap();
        }
    }

    #[test]
    fn values_are_escaped_in_defaults() {
        let t = default_template(keys::TICKET_REPLY, Locale::En).unwrap();
        let mut ctx = sample_context(keys::TICKET_REPLY);
        ctx["ticket"]["reply_excerpt"] = json!("<img src=x onerror=alert(1)>");
        ctx["ticket"]["subject"] = json!("Help\r\nBcc: evil@example.com");
        let r = render_email(&t.source(), &ctx).unwrap();
        assert!(r.html.contains("&lt;img src=x onerror=alert(1)&gt;"));
        assert!(!r.html.contains("<img"));
        assert_eq!(r.subject, "[#TKT-1042] Help Bcc: evil@example.com");
    }

    #[test]
    fn conditionals_in_defaults() {
        let t = default_template(keys::DOMAIN_EXPIRING, Locale::Tr).unwrap();
        let mut ctx = sample_context(keys::DOMAIN_EXPIRING);
        let manual = render_email(&t.source(), &ctx).unwrap();
        assert!(manual.html.contains("Alan adını yenile"));
        ctx["domain"]["auto_renew"] = json!(true);
        let auto = render_email(&t.source(), &ctx).unwrap();
        assert!(auto.html.contains("Otomatik yenileme açık"));
        assert!(!auto.html.contains("Alan adını yenile"));

        let t = default_template(keys::PASSWORD_RESET, Locale::En).unwrap();
        let mut ctx = sample_context(keys::PASSWORD_RESET);
        ctx.as_object_mut().unwrap().remove("request");
        let r = render_email(&t.source(), &ctx).unwrap();
        assert!(!r.text.contains("IP address"));
    }
}
